        button: 0,
        buttons: 1,
        clientX: endX,
        clientY: endY,
        pointerType: 'mouse',
      });
      fireEvent.mouseMove(endTarget, {
        button: 0,
        buttons: 1,
        clientX: endX,
        clientY: endY,
      });
      fireEvent.pointerUp(endTarget, {
        button: 0,
        buttons: 0,
        clientX: endX,
        clientY: endY,
        pointerType: 'mouse',
      });
      fireEvent.mouseUp(endTarget, {
        button: 0,
        buttons: 0,
        clientX: endX,
        clientY: endY,
      });

      await waitFor(() => {
        expect(screen.queryByRole('listbox')).toBe(null);
      });
      expect(screen.queryByTestId('popover-popup')).not.toBe(null);

      fireEvent.pointerDown(document.body, {
        button: 0,
        buttons: 1,
        clientX: endX,
        clientY: endY,
        pointerType: 'mouse',
      });
      fireEvent.mouseDown(document.body, {
        button: 0,
        buttons: 1,
        clientX: endX,
        clientY: endY,
      });
      fireEvent.pointerUp(document.body, {
        button: 0,
        buttons: 0,
        clientX: endX,
        clientY: endY,
        pointerType: 'mouse',
      });
      fireEvent.mouseUp(document.body, {
        button: 0,
        buttons: 0,
        clientX: endX,
        clientY: endY,
      });
      fireEvent.click(document.body, {
        button: 0,
        clientX: endX,
        clientY: endY,
      });

      await waitFor(() => {
        expect(screen.queryByTestId('popover-popup')).toBe(null);
      });
    })

